</style></head><body><main class="wrap"><div class="top"><div><h1><?= e(villa_ui('Properties')) ?></h1><p><?= e(villa_ui('Manage listings, prices and publication status.')) ?></p></div><div style="display:flex;gap:9px;flex-wrap:wrap"><a class="btn" href="<?= e(app_url('/admin/properties/locations')) ?>"><?= e(villa_ui('Bulk update locations')) ?></a><a class="btn" href="<?= e($newUrl ?? '/admin/properties/new') ?>"><?= e(villa_ui('+ New property')) ?></a></div></div><table><thead><tr><th><?= e(villa_ui('Property')) ?></th><th><?= e(villa_ui('Location')) ?></th><th><?= e(villa_ui('Capacity')) ?></th><th><?= e(villa_ui('Nightly')) ?></th><th><?= e(villa_ui('Status')) ?></th><th></th></tr></thead><tbody><?php foreach($properties as $p): ?><tr><td><strong><?= e($p['title']) ?></strong><br><small><?= e($p['slug']) ?></small></td><td><?= e(trim(($p['district'] ? $p['district'].', ' : '').($p['city'] ?? ''))) ?></td><td><?= (int)$p['max_guests'] ?> <?= e(villa_ui('people')) ?></td><td><?= e(number_format((float)$p['base_nightly_price'],0,',','.')) ?> <?= e($p['currency']) ?></td><td><span class="status"><?= e($p['status']) ?></span></td><td><a href="<?= e($editBase ?? '/admin/properties') ?>/<?= (int)$p['id'] ?>"><?= e(villa_ui('Edit')) ?></a> <a href="<?= e($editBase ?? '/admin/properties') ?>/<?= (int)$p['id'] ?>/availability"><?= e(villa_ui('Calendar')) ?></a> <form method="post" action="<?= e($deleteAction ?? '/admin/properties/delete') ?>" style="display:inline" onsubmit="return confirm('Bu ilan silinsin mi?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button type="submit" style="border:0;background:none;color:#b33;cursor:pointer"><?= e(villa_ui('Delete')) ?></button></form></td></tr><?php endforeach; ?><?php if(!$properties): ?><tr><td colspan="6"><?= e(villa_ui('No properties yet.')) ?></td></tr><?php endif; ?></tbody></table><p><a href="<?= e($backUrl ?? '/admin') ?>">← Geri</a></p></main></body></html>